def poly(x, d):
    import itertools
    t = [t for k in range(d + 1) for t in itertools.combinations_with_replacement(range(x.shape[1]), k)]
    return (np.column_stack([np.prod(x[:, q], axis=1) for q in t]), t)

def stats(a, y):
    p = np.linalg.pinv(a)
    c = p @ y
    e = y - a @ c
    loo = e / (1 - (a * p.T).sum(1))[:, None]
    return (c, np.sqrt(np.mean(e ** 2)), np.sqrt(np.mean(loo ** 2)), np.max(np.abs(loo)))
